CREATE OR REPLACE FUNCTION pg_temp.team_check(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',message; END IF; END $$;
CREATE OR REPLACE FUNCTION pg_temp.team_reject(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN EXECUTE statement;RAISE EXCEPTION 'Unexpected success: %',statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>expected THEN RAISE; END IF; END $$;
GRANT EXECUTE ON FUNCTION pg_temp.team_check(boolean,text),pg_temp.team_reject(text,text) TO authenticated,anon,service_role;
UPDATE auth.users SET email_confirmed_at=now() WHERE id::text LIKE 'e8310000-%';
CREATE TEMP TABLE membership_tokens(code uuid,version uuid,member_version uuid);
INSERT INTO membership_tokens DEFAULT VALUES;GRANT SELECT,UPDATE ON membership_tokens TO authenticated;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000001',false);
UPDATE membership_tokens SET code=(public.get_centre_link_code()->>'code')::uuid;
SELECT pg_temp.team_check((public.get_centre_link_code()->>'code')::uuid=(SELECT code FROM membership_tokens),'Code retry is stable');
SELECT pg_temp.team_check(public.get_my_centre_lessons(now(),now()+interval '10 days')->'items'='[]','No membership means no lessons');
SELECT pg_temp.team_reject($q$SELECT public.get_my_centre_lessons(now(),now()+interval '33 days')$q$,'22023');
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000006',false);
SELECT public.save_centre_instructor('e8310000-0000-0000-0006-000000000010','Persona collegata',true);
UPDATE membership_tokens SET member_version=(SELECT (m->>'version')::uuid FROM jsonb_array_elements(public.get_my_centre_team()->'members') m WHERE m->>'id'='e8310000-0000-0000-0006-000000000010');
SELECT pg_temp.team_reject($q$SELECT public.invite_centre_account(gen_random_uuid(),'e8310000-0000-0000-0006-000000000010','00000000-0000-0000-0000-000000000000',(SELECT member_version FROM membership_tokens))$q$,'22023');
UPDATE membership_tokens SET version=(public.invite_centre_account('e8310000-0000-0000-0007-000000000001','e8310000-0000-0000-0006-000000000010',code,member_version)->>'version')::uuid;
SELECT pg_temp.team_check((public.invite_centre_account('e8310000-0000-0000-0007-000000000001','e8310000-0000-0000-0006-000000000010',code,member_version)->>'version')::uuid=version,'Invite retry preserves request') FROM membership_tokens;
SELECT pg_temp.team_reject($q$SELECT public.change_centre_membership('e8310000-0000-0000-0007-000000000001','accept',(SELECT version FROM membership_tokens))$q$,'42501');
RESET ROLE;SELECT set_config('request.jwt.claim.sub','',false);
